usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/uniondepot"
	"github.com/example/uniondepot/option"
)

func main() {
	client := uniondepot.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Shapes.Get(context.TODO(), "shape_id")
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
